/** Ephemeral thread metadata. Lives at the tail of [`ThreadRecord`]. Ephemeral threads are spawned for short-lived agent work that should not crowd `heddle log` or the thread workspace. If not promoted before `ttl_seconds` elapses, the thread auto-collapses on the next read-side sweep (`heddle status`, `heddle log`, `heddle thread list`). */
export interface EphemeralMarker {
  /** When `true` (the default), the auto-collapse sweep collapses the thread on TTL expiry. Setting `false` produces a warning at expiry but leaves the thread alive — useful for "ephemeral but I'm not done yet" situations during debugging. */
  auto_collapse?: boolean;
  /** When this marker was attached. Usually equal to the thread's own `created_at`, but kept separately so a thread can be retroactively marked ephemeral by a later operation if we ever need to. */
  created_at: string;
  /** Time-to-live, in seconds, measured from [`ThreadRecord::created_at`]. */
  ttl_seconds: number;
}

